CREATE TABLE IF NOT EXISTS users ( id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, pw TEXT NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, fails INTEGER NOT NULL DEFAULT 0, locked_until INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS invites ( code TEXT PRIMARY KEY, created_by INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, used_by INTEGER, used_at INTEGER );
CREATE TABLE IF NOT EXISTS accounts ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, email TEXT NOT NULL UNIQUE, refresh_token TEXT NOT NULL, root_folder_id TEXT, quota_limit INTEGER, quota_usage INTEGER, quota_at INTEGER, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS files ( id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, name TEXT NOT NULL, folder TEXT NOT NULL DEFAULT '', size INTEGER NOT NULL, mime TEXT NOT NULL DEFAULT 'application/octet-stream', nparts INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'uploading', created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS parts ( file_id TEXT NOT NULL, idx INTEGER NOT NULL, account_id INTEGER NOT NULL, size INTEGER NOT NULL, drive_id TEXT, session_url TEXT, PRIMARY KEY (file_id, idx) );
CREATE TABLE IF NOT EXISTS folders ( user_id INTEGER NOT NULL, path TEXT NOT NULL, PRIMARY KEY (user_id, path) );
CREATE INDEX IF NOT EXISTS idx_files_user ON files(user_id, folder);
CREATE INDEX IF NOT EXISTS idx_parts_account ON parts(account_id);
CREATE INDEX IF NOT EXISTS idx_accounts_user ON accounts(user_id);
CREATE TABLE IF NOT EXISTS shares ( token TEXT PRIMARY KEY, file_id TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS moves ( file_id TEXT NOT NULL, idx INTEGER NOT NULL, to_account INTEGER NOT NULL, session_url TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (file_id, idx) );
